<script setup>
import FinancialWorkspace from '../../../Components/Accounting/FinancialWorkspace.vue'
import { ref } from 'vue'
import { Link, Head, router, useForm } from '@inertiajs/vue3'
import AdminLayout from '../../../Layouts/AdminLayout.vue'
import PageHeader from '../../../Components/Ui/PageHeader.vue'
import AccountingNav from '../../../Components/Accounting/AccountingNav.vue'
import AccountingPanel from '../../../Components/Accounting/AccountingPanel.vue'
import Pagination from '../../../Components/Ui/Pagination.vue'
import { useConfirm } from '../../../Composables/useConfirm'
defineOptions({layout:AdminLayout})
const props=defineProps({years:Object,urls:Object});const {ask}=useConfirm();const year=new Date().getFullYear();const createForm=useForm({name:`السنة المالية ${year}`,starts_on:`${year}-01-01`,ends_on:`${year}-12-31`,notes:'',create_monthly_periods:true});const editForm=useForm({name:'',starts_on:'',ends_on:'',notes:''});const editingId=ref(null)
const create=()=>createForm.post(props.urls.store,{preserveScroll:true});function edit(item){editingId.value=item.id;Object.assign(editForm,{name:item.name,starts_on:item.startsOn,ends_on:item.endsOn,notes:item.notes||''})}const save=(item)=>editForm.put(item.updateUrl,{preserveScroll:true,onSuccess:()=>editingId.value=null})
async function action(item,type){const closing=type==='close';const yes=await ask({title:closing?'إقفال السنة المالية؟':'إعادة فتح السنة؟',message:closing?'يجب إقفال شهورها أولاً. عندها ينشئ النظام قيد النتيجة السنوي مرة واحدة ويحمي السنة من الترحيل.':'سيُعكس قيد النتيجة السنوي وتعود السنة إلى حالة مفتوحة.',confirmLabel:closing?'إقفال السنة':'إعادة الفتح',danger:closing});if(yes)router.post(closing?item.closeUrl:item.reopenUrl,{}, {preserveScroll:true})}async function remove(item){const yes=await ask({title:'حذف السنة؟',message:'لن يسمح النظام بالحذف إذا وُجدت قيود ضمن المدة.',confirmLabel:'حذف السنة',danger:true});if(yes)router.delete(item.destroyUrl,{preserveScroll:true})}
const checkingId = ref(null)
function check(item) { checkingId.value = item.id; router.get(item.checkUrl, {}, { only: ['years'], preserveState: true, preserveScroll: true, onFinish: () => { checkingId.value = null } }) }
</script>
<template>
<Head title="السنوات المالية"/>
<FinancialWorkspace area="المحاسبة" mode="records">
<template #heading>
<PageHeader title="السنوات المالية" icon="bi-calendar2-check-fill" subtitle="السنوات وشهورها المحاسبية"/>
</template>
<template #navigation>
<AccountingNav :urls="urls" active="fiscalYears"/>
</template>
<div class="year-layout"><AccountingPanel title="سنة مالية جديدة" description="في معظم المطاعم: سنة ميلادية و12 شهراً تلقائياً." icon="bi-calendar-plus"><form class="create-form" @submit.prevent="create"><label><span>اسم السنة</span><input v-model="createForm.name" class="form-control" required></label><div><label><span>من</span><input v-model="createForm.starts_on" type="date" class="form-control" required></label><label><span>إلى</span><input v-model="createForm.ends_on" type="date" class="form-control" required></label></div><label><span>ملاحظات</span><textarea v-model="createForm.notes" rows="2" class="form-control"></textarea></label><label class="auto"><input v-model="createForm.create_monthly_periods" type="checkbox"><span><strong>إنشاء الشهور تلقائياً</strong><small>ينشئ فترة لكل شهر داخل السنة ويمكن تعديلها لاحقاً.</small></span></label><button class="btn btn-primary"><i class="bi bi-plus-lg"></i> إنشاء السنة</button></form></AccountingPanel>
<main class="year-list"><article v-for="item in years.data" :key="item.id" class="year-card" :class="{closed:item.closed}"><header><span><i class="bi" :class="item.closed?'bi-lock-fill':'bi-calendar2-check'"></i></span><div><div><strong>{{item.name}}</strong><em :class="item.closed?'closed':'open'">{{item.closed?'مقفلة':'مفتوحة'}}</em></div><small>{{item.startsOn}} — {{item.endsOn}}</small><p v-if="item.notes">{{item.notes}}</p></div><section><strong>{{item.closedPeriods}} / {{item.periods.length}}</strong><small>شهر مقفل</small></section></header><div v-if="item.periods.length" class="months"><span v-for="period in item.periods" :key="period.id" :class="{closed:period.closed}" :title="period.name">{{period.month}}</span></div><div v-else class="no-months"><i class="bi bi-exclamation-circle"></i> لا توجد شهور مرتبطة بهذه السنة.</div><div v-if="!item.closed&&item.checks.length" class="checks"><span v-for="(check,i) in item.checks" :key="i" :class="check.ok?'ok':check.severity==='block'?'block':'warn'"><i class="bi" :class="check.ok?'bi-check2':'bi-exclamation' "></i>{{check.label}}</span></div><div class="actions"><button v-if="!item.closed" type="button" :disabled="checkingId !== null" @click="check(item)"><i class="bi bi-list-check"></i> {{ checkingId === item.id ? 'جارٍ الفحص…' : 'فحص الإقفال' }}</button><button type="button" @click="edit(item)"><i class="bi bi-pencil"></i> تعديل</button><Link :href="urls.periods"><i class="bi bi-calendar3"></i> الشهور</Link><span></span><button v-if="item.closed" type="button" class="reopen" @click="action(item,'reopen')"><i class="bi bi-unlock"></i> إعادة فتح</button><template v-else><button type="button" class="close" @click="action(item,'close')"><i class="bi bi-lock"></i> إقفال السنة</button><button type="button" class="delete" @click="remove(item)"><i class="bi bi-trash3"></i></button></template></div><form v-if="editingId===item.id" class="edit-form" @submit.prevent="save(item)"><label><span>الاسم</span><input v-model="editForm.name" class="form-control" required></label><label><span>من</span><input v-model="editForm.starts_on" type="date" class="form-control" required></label><label><span>إلى</span><input v-model="editForm.ends_on" type="date" class="form-control" required></label><label><span>ملاحظات</span><input v-model="editForm.notes" class="form-control"></label><button class="btn btn-primary"><i class="bi bi-check2"></i> حفظ</button><button type="button" class="btn btn-light" @click="editingId=null">إلغاء</button></form></article><div v-if="!years.data.length" class="empty"><i class="bi bi-calendar2-x"></i><strong>لا توجد سنة مالية</strong><span>أنشئ الأولى مع خيار إنشاء الشهور تلقائياً.</span></div><Pagination :links="years.links"/></main></div>
</FinancialWorkspace>

</template>
